      // Return the updated card
      const updatedCard = await db.query(
        'SELECT * FROM cards WHERE id = $1',
        [id]
      );

      res.json(updatedCard.rows[0]);
    } catch (error) {
      await db.rollback();
      res.status(500).json({ error: error.message });
    }
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// SSE endpoint
const clients = new Set();

app.get('/api/stream', (req, res) => {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  const sendEvent = (event, data) => {
    res.write(`event: ${event}\n`);
    res.write(`data: ${JSON.stringify(data)}\n\n`);
  };

  // Send initial board state
  initDB().then(async () => {
    const board = await db.query(`
      SELECT c.id, c.title, c.position, 
             json_agg(
               json_build_object(
                 'id', ca.id,
                 'text', ca.text,
                 'position', ca.position,
                 'created_at', ca.created_at
               ) ORDER BY ca.position ASC
             ) AS cards
      FROM columns c
      LEFT JOIN cards ca ON c.id = ca.column_id
      GROUP BY c.id, c.title, c.position
      ORDER BY c.position ASC;
    `);

    sendEvent('initialState', board.rows);
  });

  // Add client to the set
  const clientId = Date.now();
  const client = {
    id: clientId,
    res: res
  };

  clients.add(client);

  // Remove client from the set on connection close
  req.on('close', () => {
    clients.delete(client);
  });
});

// Broadcast function
const broadcast = (event, data) => {
  clients.forEach(client => {
    client.res.write(`event: ${event}\n`);
    client.res.write(`data: ${JSON.stringify(data)}\n\n`);
  });
};

// Start server
initDB().then(() => {
  app.listen(port, () => {
    console.log(`Server running at http://localhost:${port}`);
  });
});
