```javascript
// frontend/src/main.js
import './style.css';

document.addEventListener('DOMContentLoaded', () => {
  const boardElement = document.getElementById('board');
  const eventSource = new EventSource('http://localhost:3000/api/stream');

  // Function to render the board
  async function renderBoard() {
    const response = await fetch('http://localhost:3000/api/board');
    const boardData = await response.json();

    boardElement.innerHTML = '';

    boardData.forEach(column => {
      const columnElement = document.createElement('div');
      columnElement.className = 'column';
      columnElement.dataset.columnId = column.id;

      const columnTitle = document.createElement('h2');
      columnTitle.textContent = column.title;

      const addCardInput = document.createElement('input');
      addCardInput.type = 'text';
      addCardInput.placeholder = 'Add a card...';

      const addCardButton = document.createElement('button');
      addCardButton.textContent = 'Add';

      addCardButton.addEventListener('click', async () => {
        const text = addCardInput.value.trim();
        if (text) {
          // Optimistically add the card to the UI
          const cardElement = createCardElement(text);
          columnElement.querySelector('.cards').appendChild(cardElement);
          addCardInput.value = '';

          // Send request to server
          try {
            const response = await fetch('http://localhost:3000/api/cards', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
              },
              body: JSON.stringify({
                columnId: column.id,
                text: text
              }),
            });

            const card = await response.json();
            cardElement.dataset.cardId = card.id;
          } catch (error) {
            // If request fails, remove the optimistically added card
            cardElement.remove();
            console.error('Error adding card:', error);
          }
        }
      });

      const cardsContainer = document.createElement('div');
      cardsContainer.className = 'cards';

      // Sort cards by position
      const sortedCards = column.cards.sort((a, b) => a.position - b.position);

      sortedCards.forEach(card => {
        const cardElement = createCardElement(card.text);
        cardElement.dataset.cardId = card.id;
        cardsContainer.appendChild(cardElement);
      });

      columnElement.appendChild(columnTitle);
      columnElement.appendChild(addCardInput);
      columnElement.appendChild(addCardButton);
      columnElement.appendChild(cardsContainer);

      boardElement.appendChild(columnElement);
    });

    // Add drag and drop functionality
    setupDragAndDrop();
  }

  // Function to create a card element
  function createCardElement(text) {
    const cardElement = document.createElement('div');
    cardElement.className = 'card';
    cardElement.draggable = true;
    cardElement.textContent = text;

    return cardElement;
  }

  // Function to set up drag and drop
  function setupDragAndDrop() {
    const cards = document.querySelectorAll('.card');
    const columns = document.querySelectorAll('.column');

    let draggedCard = null;

    cards.forEach(card => {
      card.addEventListener('dragstart', (e) => {
        draggedCard = card;
        setTimeout(() => {
          card.style.opacity = '0.5';
        }, 0);
      });

      card.addEventListener('dragend', () => {
        card.style.opacity = '1';
      });
    });

    columns.forEach(column => {
      const cardsContainer = column.querySelector('.cards');

      cardsContainer.addEventListener('dragover', (e) => {
        e.preventDefault();
        const afterElement = getDragAfterElement(cardsContainer, e.clientY);
        if (afterElement == null) {
          cardsContainer.appendChild(draggedCard);
        } else {
          cardsContainer.insertBefore(draggedCard, afterElement);
        }
      });

      cardsContainer.addEventListener('drop', (e) => {
        e.preventDefault();
        const cardId = draggedCard.dataset.cardId;
        const columnId = column.dataset.columnId;
        const beforeId = getCardBeforeId(cardsContainer, draggedCard);
        const afterId = getCardAfterId(cardsContainer, draggedCard);

        // Optimistically update the UI
        // The card is already in the new position from the drag-and-drop

        // Send request to server
        fetch(`http://localhost:3000/api/cards/${cardId}/move`, {
          method: 'PATCH',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            columnId: columnId,
            beforeId: beforeId,
            afterId: afterId
          }),
        }).catch(error => {
          console.error('Error moving card:', error);
          // If request fails, revert the optimistic update
          const originalColumn = document.querySelector(`.column[data-column-id="${draggedCard.dataset.originalColumnId}"]`);
          const originalCardsContainer = originalColumn.querySelector('.cards');
          originalCardsContainer.appendChild(draggedCard);
        });
      });
    });
  }

  // Helper function to get the element after which to drop
  function getDragAfterElement(container, y) {
    const draggableElements = [...container.querySelectorAll('.card:not(.dragging)')];

    return draggableElements.reduce((closest, child) => {
      const box = child.getBoundingClientRect();
      const offset = y - box.top - box.height / 2;

      if (offset < 0 && offset > closest.offset) {
        return { offset: offset, element: child };
      } else {
        return closest;
      }
    }, { offset: Number.NEGATIVE_INFINITY }).element;
  }

  // Helper function to get the ID of the card before the dragged card
  function getCardBeforeId(container, card) {
    const cards = [...container.querySelectorAll('.card')];
    const index = cards.indexOf(card);

    if (index > 0) {
      return cards[index - 1].dataset.cardId;
    }

    return null;
  }

  // Helper function to get the ID of the card after the dragged card
  function getCardAfterId(container, card) {
    const cards = [...container.querySelectorAll('.card')];
    const index = cards.indexOf(card);

    if (index < cards.length - 1) {
      return cards[index + 1].dataset.cardId;
    }

    return null;
  }

  // Listen for SSE events
  eventSource.onmessage = (event) => {
    const data = JSON.parse(event.data);
    renderBoard();
  };

  eventSource.onerror = (error) => {
    console.error('EventSource error:', error);
    eventSource.close();
  };

  // Initial render
  renderBoard();
});
